// Test helper; compile only in GitHub Actions. Historical parser/workload kept for comparability.
package main
import("encoding/binary";"encoding/json";"flag";"fmt";"io";"net";"os";"sort";"strings";"sync";"time")
var order=binary.BigEndian
type Job struct{I int;At time.Time}
type Sample struct{I int `json:"i"`;Name string `json:"name"`;Type int `json:"type"`;MS float64 `json:"ms"`;Late float64 `json:"late_ms"`;Error string `json:"error,omitempty"`}
func u16(b []byte,n int)int{return int(order.Uint16(b[n:n+2]))}
func skip(b []byte,p int)(int,error){for i:=0;i<128;i++{if p>=len(b){break};v:=int(b[p]);p++;if v==0{return p,nil};if v&192==192{if p<len(b){return p+1,nil};break};if v>63||p+v>len(b){break};p+=v};return 0,fmt.Errorf("invalid name")}
func valid(q,r []byte,typ int)error{if len(r)<12||u16(r,0)!=u16(q,0)||u16(r,2)&0x8000==0{return fmt.Errorf("header")};if u16(r,2)&15!=0{return fmt.Errorf("rcode_%d",u16(r,2)&15)};if u16(r,2)&512!=0{return fmt.Errorf("truncated")};if u16(r,4)!=1{return fmt.Errorf("questions")};p,e:=skip(r,12);if e!=nil||p+4>len(r){return fmt.Errorf("question")};end,_:=skip(q,12);if string(r[12:p+4])!=string(q[12:end+4]){return fmt.Errorf("question_mismatch")};p+=4;found:=false;for j:=0;j<u16(r,6);j++{p,e=skip(r,p);if e!=nil||p+10>len(r){return fmt.Errorf("rr")};t:=u16(r,p);cl:=u16(r,p+2);l:=u16(r,p+8);p+=10;if p+l>len(r){return fmt.Errorf("rdata")};if t==typ&&cl==1&&((t==1&&l==4)||(t==28&&l==16)){found=true};p+=l};if !found{return fmt.Errorf("no_address_answer")};return nil}
func query(id int,name string,typ int,cold bool)[]byte{b:=make([]byte,12);order.PutUint16(b,uint16(id));order.PutUint16(b[2:],256);order.PutUint16(b[4:],1);for _,l:=range strings.Split(name,"."){b=append(b,byte(len(l)));b=append(b,[]byte(l)...)};b=append(b,0,byte(typ>>8),byte(typ),0,1);if cold{order.PutUint16(b[10:],1);b=append(b,0,0,41,4,208,0,0,0,0,0,12,0,10,0,8);cookie:=make([]byte,8);order.PutUint64(cookie,uint64(time.Now().UnixNano())^uint64(id));b=append(b,cookie...)};return b}
func pct(a []float64,p float64)float64{if len(a)==0{return 0};sort.Float64s(a);i:=int(float64(len(a)-1)*p);return a[i]}
func main(){addr:=flag.String("addr","127.0.0.1:15531","");network:=flag.String("net","udp","");rate:=flag.Int("rate",50,"");seconds:=flag.Int("seconds",20,"");workers:=flag.Int("workers",32,"");cold:=flag.Bool("cold",false,"");group:=flag.String("group","mixed","");kind:=flag.String("type","mixed","");nameFlag:=flag.String("name","","");unique:=flag.Bool("unique",false,"");offset:=flag.Int("offset",0,"");flag.Parse();if *rate<1||*rate>4000||*seconds<1||*seconds>60||*workers<1||*workers>32{panic("bounds")};names:=[]string{"www.baidu.com","www.qq.com","example.com","www.cloudflare.com"};if *group=="cn"{names=names[:2]};if *group=="foreign"{names=names[2:]};n:=*rate**seconds;samples:=make([]Sample,n);jobs:=make(chan Job);var wg sync.WaitGroup;start:=time.Now().Add(100*time.Millisecond);var mu sync.Mutex;sent:=0;first,last:=time.Time{},time.Time{};for w:=0;w<*workers;w++{wg.Add(1);go func(){defer wg.Done();var c net.Conn;defer func(){if c!=nil{c.Close()}}();for j:=range jobs{now:=time.Now();mu.Lock();sent++;if first.IsZero()||now.Before(first){first=now};if now.After(last){last=now};mu.Unlock();typ:=1;if j.I%2==1{typ=28};if *kind=="A"{typ=1}else if *kind=="AAAA"{typ=28};name:=names[(j.I/2)%len(names)];if *nameFlag!=""{name=*nameFlag};if *unique{name=fmt.Sprintf("q%d.cn.test",j.I+*offset)};s:=Sample{I:j.I,Name:name,Type:typ,Late:float64(now.Sub(j.At).Microseconds())/1000};q:=query(j.I+1,name,typ,*cold);var e error;if c==nil{c,e=net.DialTimeout(*network,*addr,time.Second)};if e==nil{c.SetDeadline(now.Add(2*time.Second));var r []byte;if *network=="tcp"{buf:=append([]byte{byte(len(q)>>8),byte(len(q))},q...);_,e=c.Write(buf);if e==nil{h:=make([]byte,2);_,e=io.ReadFull(c,h);if e==nil{r=make([]byte,u16(h,0));_,e=io.ReadFull(c,r)}}}else{_,e=c.Write(q);if e==nil{buf:=make([]byte,4096);for{var k int;k,e=c.Read(buf);if e!=nil{break};if k>=2&&u16(buf,0)==u16(q,0){r=buf[:k];break}}}};if e==nil{e=valid(q,r,typ)}};s.MS=float64(time.Since(now).Microseconds())/1000;if e!=nil{s.Error=e.Error();if c!=nil{c.Close();c=nil}};samples[j.I]=s}}()};missed:=0;for i:=0;i<n;i++{at:=start.Add(time.Duration(i)*time.Second/time.Duration(*rate));time.Sleep(time.Until(at));if time.Since(at)>10*time.Millisecond{samples[i]=Sample{I:i,Error:"scheduler_late_over_10ms"};missed++;continue};select{case jobs<-Job{i,at}:default:samples[i]=Sample{I:i,Error:"inflight_limit"};missed++}};close(jobs);wg.Wait();lat,late:=[]float64{},[]float64{};errors:=map[string]int{};ok:=0;for _,s:=range samples{if s.Error!=""{errors[s.Error]++}else{ok++;lat=append(lat,s.MS)};if s.Error!="scheduler_late_over_10ms"&&s.Error!="inflight_limit"{late=append(late,s.Late)}};res:=map[string]any{"query_type":*kind,"addr":*addr,"net":*network,"rate":*rate,"seconds":*seconds,"workers":*workers,"cold_cookie_bypass":*cold,"group":*group,"offered":n,"sent":sent,"success":ok,"unsent":missed,"success_qps":float64(ok)/float64(*seconds),"success_of_offered_percent":float64(ok)*100/float64(n),"p50_ms":pct(lat,.5),"p95_ms":pct(lat,.95),"p99_ms":pct(lat,.99),"max_ms":pct(lat,1),"send_late_p99_ms":pct(late,.99),"first_send":first,"last_send":last,"errors":errors,"samples":samples};json.NewEncoder(os.Stdout).Encode(res)}
